package cn.mop.api;

import cn.mop.domain.*;
import cn.mop.domain.inspection.InspectionTemplate;
import cn.mop.domain.inspection.InspectionTemplate.Item;
import cn.mop.domain.inspection.InspectionTemplateRepository;
import cn.mop.domain.inspection.InspectionTemplateRepository.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.mockito.ArgumentCaptor;
import org.springframework.mock.web.MockHttpServletRequest;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** Isolated controller boundaries only; actual PG/OIDC/CSRF HTTP proof is separate. */
class InspectionTemplateControllerTest {
    static final String ACTOR="79000000-0000-4000-8000-000000000001",TENANT="79000000-0000-4000-8000-000000000002",ID="79000000-0000-4000-8000-000000000003";
    PlatformRepository platform;InspectionTemplateRepository repository;InspectionTemplateController controller;ObjectMapper mapper=new ObjectMapper();
    @BeforeEach void setup(){platform=mock(PlatformRepository.class);repository=mock(InspectionTemplateRepository.class);controller=new InspectionTemplateController(platform,repository);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"padmin",7,true)));when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(call->{((Runnable)call.getArgument(6)).run();return ((Supplier<?>)call.getArgument(7)).get();});when(repository.create(any(),anyLong(),any())).thenAnswer(call->row(1,"CREATE",false,call.getArgument(2)));when(repository.update(any(),any(),anyLong(),any())).thenAnswer(call->row(2,"UPDATE",false,call.getArgument(3)));when(repository.restore(any(),any(),anyLong(),any())).thenAnswer(call->row(3,"RESTORE",false,call.getArgument(3)));when(repository.archive(any(),any(),anyLong())).thenReturn(row(2,"ARCHIVE",true,definition()));}
    Access access(){return new Access(ACTOR,TENANT,7,"inspection-test");}
    MockHttpServletRequest request(String method){var request=new MockHttpServletRequest(method,"/api/v1/inspection-templates");request.setUserPrincipal(()->ACTOR);request.getSession().setAttribute("mop.tenant_id",TENANT);request.setAttribute("mop.trace_id","inspection-test");request.addHeader("Idempotency-Key","inspection-test-key");return request;}
    InspectionTemplate definition(){return new InspectionTemplate("new_device","合成模板",List.of(new Item("firmware","安全","固件",null)));}
    Entry row(long version,String action,boolean archived,InspectionTemplate definition){Instant time=Instant.parse("2026-10-04T08:00:00.123Z");return new Entry(ID,TENANT,ACTOR,version,time,time,ACTOR,time,action,archived,InspectionTemplate.Snapshot.capture(UUID.fromString(TENANT),UUID.fromString(ID),version,definition));}
    ObjectNode input(){var value=mapper.createObjectNode().put("expected_version",0).put("device_type","new_device").put("name","合成模板");value.putArray("items").addObject().put("key","firmware").put("section","安全").put("label","固件").putNull("instruction");return value;}
    Map<?,?> data(Object value){return (Map<?,?>)((Map<?,?>)value).get("data");}
    @Test void createKeepsExplicitNullAndUnapprovedNoPublishNoScanFacts(){var value=data(controller.write(null,"CREATE",input(),request("POST")));assertEquals(ID,value.get("id"));assertEquals(1L,value.get("version"));assertEquals("UNVERIFIED",value.get("approval_status"));assertEquals("NOT_IMPLEMENTED",value.get("publication_status"));assertEquals(false,value.get("report_published"));assertEquals(false,value.get("active_scan_performed"));assertEquals(definition().fingerprint(),value.get("content_sha256"));assertNull(((Map<?,?>)((List<?>)value.get("items")).get(0)).get("instruction"));verify(repository).authorizeWrite(access(),null);}
    @Test void fullExplicitUpdateAndRestoreKeepNewRevisionSeparate(){var body=input().put("expected_version",1);assertEquals(2L,data(controller.write(ID,"UPDATE",body,request("PATCH"))).get("version"));assertEquals(3L,data(controller.write(ID,"RESTORE",body,request("POST"))).get("version"));verify(repository).update(eq(access()),eq(ID),eq(1L),any());verify(repository).restore(eq(access()),eq(ID),eq(1L),any());assertThrows(DomainException.class,()->controller.write(ID,"RESTORE",mapper.createObjectNode().put("expected_version",1),request("POST")));}
    @Test void archiveAllowsOnlyVersionAndCopiesStoredDefinition(){var value=data(controller.write(ID,"ARCHIVE",mapper.createObjectNode().put("expected_version",1),request("POST")));assertEquals(true,value.get("archived"));assertEquals(definition().fingerprint(),value.get("content_sha256"));assertThrows(DomainException.class,()->controller.write(ID,"ARCHIVE",input().put("expected_version",1),request("POST")));}
    @Test void allOtherRolesFailBeforeBodyParseAndNoTemplateCalls(){for(String role:List.of("tadmin","msp","viewer","unknown")){when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,role,7,true)));var request=request("POST");request.setContent("not-json".getBytes(StandardCharsets.UTF_8));assertEquals(403,assertThrows(DomainException.class,()->controller.create(request)).status);assertEquals(403,assertThrows(DomainException.class,()->controller.list(request("GET"))).status);}verifyNoInteractions(repository);}
    @Test void missingInactiveAndMalformedSessionsCannotRead(){var request=request("GET");request.setUserPrincipal(null);assertEquals(401,assertThrows(DomainException.class,()->controller.list(request)).status);request.setUserPrincipal(()->ACTOR);request.getSession().setAttribute("mop.tenant_id",42);assertEquals(401,assertThrows(DomainException.class,()->controller.list(request)).status);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"padmin",7,false)));assertEquals(401,assertThrows(DomainException.class,()->controller.list(request("GET"))).status);verifyNoInteractions(repository);}
    @Test void expectedVersionsAndExtraScopeOrApprovalFieldsAreRejected(){for(JsonNode version:List.of(IntNode.valueOf(1),IntNode.valueOf(-1),TextNode.valueOf("0"),DoubleNode.valueOf(0.0))){var body=input();body.set("expected_version",version);assertThrows(DomainException.class,()->controller.write(null,"CREATE",body,request("POST")));}for(String key:List.of("tenant_id","approval_status","report_published","active_scan_performed"))assertThrows(DomainException.class,()->controller.write(null,"CREATE",input().put(key,"forged"),request("POST")));assertThrows(DomainException.class,()->controller.write(ID,"UPDATE",input().put("expected_version",9007199254740990L),request("PATCH")));}
    @Test void missingRootAndItemFieldsNeverBecomeDefaults(){for(String field:List.of("name","device_type","items","expected_version")){var body=input();body.remove(field);assertThrows(DomainException.class,()->controller.write(null,"CREATE",body,request("POST")));}for(String field:List.of("key","section","label","instruction")){var body=input();((ObjectNode)body.path("items").get(0)).remove(field);assertThrows(DomainException.class,()->controller.write(null,"CREATE",body,request("POST")));}}
    @Test void emptyDuplicateNullAndTooManyItemsAreRejected(){for(String raw:List.of("[]","null","[null]","{}")){var body=input();try{body.set("items",mapper.readTree(raw));}catch(Exception failure){throw new IllegalStateException(failure);}assertThrows(DomainException.class,()->controller.write(null,"CREATE",body,request("POST")));}var body=input();var items=(ArrayNode)body.get("items");items.add(items.get(0).deepCopy());assertThrows(DomainException.class,()->controller.write(null,"CREATE",body,request("POST")));var many=input();var array=many.putArray("items");for(int i=0;i<101;i++)array.addObject().put("key","item_"+i).put("section","分组").put("label","项目").putNull("instruction");assertThrows(DomainException.class,()->controller.write(null,"CREATE",many,request("POST")));}
    @Test void textBoundsAndUnsupportedControlsAreRejectedWithoutTrimming(){for(String name:List.of("","　","x\u0000","\ud800","😀".repeat(201)))assertThrows(DomainException.class,()->controller.write(null,"CREATE",input().put("name",name),request("POST")));var body=input().put("name","  原文  ");((ObjectNode)body.path("items").get(0)).put("instruction","");var value=data(controller.write(null,"CREATE",body,request("POST")));assertEquals("  原文  ",value.get("name"));assertEquals("",((Map<?,?>)((List<?>)value.get("items")).get(0)).get("instruction"));}
    @Test void canonicalHashIgnoresObjectKeyOrderButKeepsItemOrderAndNullVersusEmpty()throws Exception{var first=input();((ArrayNode)first.get("items")).addObject().put("key","backup").put("section","备份").put("label","验证").putNull("instruction");var reordered=(ObjectNode)mapper.readTree("{\"name\":\"合成模板\",\"items\":[{\"instruction\":null,\"label\":\"固件\",\"section\":\"安全\",\"key\":\"firmware\"},{\"instruction\":null,\"label\":\"验证\",\"section\":\"备份\",\"key\":\"backup\"}],\"device_type\":\"new_device\",\"expected_version\":0}");var reverse=first.deepCopy();var rows=reverse.putArray("items");rows.add(first.path("items").get(1));rows.add(first.path("items").get(0));var empty=first.deepCopy();((ObjectNode)empty.path("items").get(0)).put("instruction","");for(var body:List.of(first,reordered,reverse,empty))controller.write(null,"CREATE",body,request("POST"));var hashes=ArgumentCaptor.forClass(String.class);verify(platform,times(4)).idempotentAuthorized(any(),any(),any(),any(),hashes.capture(),anyLong(),any(),any());var actual=hashes.getAllValues();assertEquals(actual.get(0),actual.get(1));assertNotEquals(actual.get(0),actual.get(2));assertNotEquals(actual.get(0),actual.get(3));}
    @Test void replayReauthorizesAndNeverExecutesMutationAgain(){doAnswer(call->{((Runnable)call.getArgument(6)).run();return Map.of("original",true);}).when(platform).idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any());assertEquals(true,data(controller.write(ID,"ARCHIVE",mapper.createObjectNode().put("expected_version",1),request("POST"))).get("original"));verify(repository).authorizeWrite(access(),ID);verify(repository,never()).archive(any(),any(),anyLong());}
    @Test void listContainsBoundedSummariesNotLargeItemText(){when(repository.list(eq(access()),eq(""),isNull(),eq(View.CURRENT),eq(16),isNull(),isNull())).thenReturn(Collections.nCopies(16,row(1,"CREATE",false,definition())));var page=data(controller.list(request("GET")));assertEquals(true,page.get("has_more"));var rows=(List<?>)page.get("items");assertEquals(15,rows.size());assertFalse(((Map<?,?>)rows.get(0)).containsKey("items"));assertEquals(ID,page.get("next_before_id"));verify(platform,never()).idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any());}
    @Test void detailAndHistoryExposeFrozenDefinitionWithoutImplicitWriting(){when(repository.get(access(),ID)).thenReturn(row(1,"CREATE",false,definition()));assertEquals(1,((List<?>)data(controller.get(ID,request("GET"))).get("items")).size());when(repository.history(eq(access()),eq(ID),eq(16),isNull())).thenReturn(List.of(new Revision(1,null,ACTOR,Instant.EPOCH,"CREATE",false,row(1,"CREATE",false,definition()).snapshot())));assertEquals(false,data(controller.history(ID,request("GET"))).get("has_more"));verify(platform,never()).idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any());}
    @Test void queryWhitelistDuplicateAndUnpairedCursorsFail(){var unknown=request("GET");unknown.addParameter("tenant_id",TENANT);var duplicate=request("GET");duplicate.addParameter("page_size","10","15");var unpaired=request("GET");unpaired.addParameter("before_id",ID);for(var request:List.of(unknown,duplicate,unpaired))assertThrows(DomainException.class,()->controller.list(request));var write=request("POST");write.addParameter("anything","x");assertThrows(DomainException.class,()->controller.write(null,"CREATE",input(),write));}
    @Test void boundedJsonRejectsDuplicatesDeepTrailingAndOversizeBodies(){for(String raw:List.of("{} {}","[[[[[1]]]]]","{\"items\":[],\"items\":[]}","{\"items\":[{\"key\":\"a\",\"key\":\"b\"}]}"," ".repeat(InspectionTemplateController.MAX_BODY_BYTES+1))){var request=request("POST");request.setContent(raw.getBytes(StandardCharsets.UTF_8));assertThrows(DomainException.class,()->controller.create(request));}var keyless=request("POST");keyless.removeHeader("Idempotency-Key");assertThrows(DomainException.class,()->controller.write(null,"CREATE",input(),keyless));verifyNoInteractions(repository);}
    @Test void maximumHundredItemDefinitionFitsTheExplicitParserBudget()throws Exception{var body=input();var items=body.putArray("items");for(int i=0;i<100;i++)items.addObject().put("key","item_"+i).put("section","组").put("label","😀".repeat(200)).put("instruction","😀".repeat(2000));var request=request("POST");byte[] utf8=mapper.writeValueAsString(body).getBytes(StandardCharsets.UTF_8);assertTrue(utf8.length<=InspectionTemplateController.MAX_BODY_BYTES,"UTF-8 request bytes="+utf8.length);request.setContent(utf8);var value=data(controller.create(request));assertEquals(100,value.get("item_count"));assertEquals(100,((List<?>)value.get("items")).size());byte[] escaped=mapper.writeValueAsBytes(body);assertTrue(escaped.length>InspectionTemplateController.MAX_BODY_BYTES,"Escaped wire bytes="+escaped.length);var oversized=request("POST");oversized.setContent(escaped);assertThrows(DomainException.class,()->controller.create(oversized));}
}
